nta.declaration:
urgent chan dummy;
urgent chan start;
chan finish;

// ——————————————————————————————
// Model parameters
// ——————————————————————————————
const int NUM_ACTORS = 17;
const int NUM_EDGES = 38;
const int MAX_TOKENS = 1;

// ——————————————————————————————
// Typedefs for indices
// ——————————————————————————————
typedef int[1, NUM_ACTORS] actor_t;
typedef int[1, NUM_EDGES] edges_t;
typedef int[0, MAX_TOKENS-1] index_t;

// ——————————————————————————————
// Edge metadata (global)
// ——————————————————————————————
typedef struct {
  actor_t from;   // source actor
  actor_t to;     // destination actor
} edge_t;

edge_t edges[edges_t] ={
  { 1, 2 }, // A -> B_start
  { 1, 3 }, // A -> C_start
  { 1, 4 }, // A -> D_start
  { 1, 5 }, // A -> H_start
  { 2, 6 }, // B_start -> B
  { 3, 7 }, // C_start -> C
  { 4, 8 }, // D_start -> D
  { 5, 9 }, // H_start -> H
  { 10, 11 }, // E_start -> E
  { 12, 13 }, // F_start -> F
  { 14, 15 }, // G_start -> G
  { 16, 17 }, // I_start -> I
  { 6, 2 }, // B -> B_start
  { 7, 3 }, // C -> C_start
  { 8, 4 }, // D -> D_start
  { 9, 5 }, // H -> H_start
  { 11, 10 }, // E -> E_start
  { 13, 12 }, // F -> F_start
  { 15, 14 }, // G -> G_start
  { 17, 16 }, // I -> I_start
  { 6, 10 }, // B -> E_start
  { 7, 10 }, // C -> E_start
  { 8, 10 }, // D -> E_start
  { 11, 12 }, // E -> F_start
  { 13, 14 }, // F -> G_start
  { 15, 16 }, // G -> I_start
  { 9, 16 }, // H -> I_start
  { 10, 2 }, // E_start -> B_start
  { 10, 3 }, // E_start -> C_start
  { 10, 4 }, // E_start -> D_start
  { 12, 10 }, // F_start -> E_start
  { 14, 12 }, // G_start -> F_start
  { 16, 14 }, // I_start -> G_start
  { 16, 5 }, // I_start -> H_start
  { 2, 1 }, // B_start -> A
  { 3, 1 }, // C_start -> A
  { 4, 1 }, // D_start -> A
  { 5, 1 } // H_start -> A
};


// ——————————————————————————————————————————
// Token buffers
// ——————————————————————————————————————————
// edge_token[e][slot]
// slot ∈ {0} only
bool edge_token[NUM_EDGES+1][MAX_TOKENS] =  {
  /* unused index 0 */ { false },
  { true }, // A -> B_start
  { true }, // A -> C_start
  { true }, // A -> D_start
  { true }, // A -> H_start
  { false }, // B_start -> B
  { false }, // C_start -> C
  { false }, // D_start -> D
  { false }, // H_start -> H
  { false }, // E_start -> E
  { false }, // F_start -> F
  { false }, // G_start -> G
  { false }, // I_start -> I
  { true }, // B -> B_start
  { true }, // C -> C_start
  { true }, // D -> D_start
  { true }, // H -> H_start
  { true }, // E -> E_start
  { true }, // F -> F_start
  { true }, // G -> G_start
  { true }, // I -> I_start
  { true }, // B -> E_start
  { true }, // C -> E_start
  { true }, // D -> E_start
  { true }, // E -> F_start
  { true }, // F -> G_start
  { true }, // G -> I_start
  { true }, // H -> I_start
  { true }, // E_start -> B_start
  { true }, // E_start -> C_start
  { true }, // E_start -> D_start
  { true }, // F_start -> E_start
  { true }, // G_start -> F_start
  { true }, // I_start -> G_start
  { true }, // I_start -> H_start
  { true }, // B_start -> A
  { true }, // C_start -> A
  { true }, // D_start -> A
  { true } // H_start -> A
};

// ——————————————————————————————————————————
// Actor ready-flags
// ——————————————————————————————————————————
// actor_ready[a][slot] = true iff all incoming edges into a carry a token
bool actor_ready[NUM_ACTORS+1][MAX_TOKENS] = {
  /* unused actor 0 */ { false },
  { true }, // actor 1 (A)
  { false }, // actor 2 (B_start)
  { false }, // actor 3 (C_start)
  { false }, // actor 4 (D_start)
  { false }, // actor 5 (H_start)
  { false }, // actor 6 (B)
  { false }, // actor 7 (C)
  { false }, // actor 8 (D)
  { false }, // actor 9 (H)
  { false }, // actor 10 (E_start)
  { false }, // actor 11 (E)
  { false }, // actor 12 (F_start)
  { false }, // actor 13 (F)
  { false }, // actor 14 (G_start)
  { false }, // actor 15 (G)
  { false }, // actor 16 (I_start)
  { false } // actor 17 (I)
};


// ——————————————————————————————
// Query: has actor `act` all inputs at slot `idx`?
// (i.e. is it *not* empty?)
// ——————————————————————————————
bool empty(actor_t act, index_t idx) {
  return not actor_ready[act][idx];
}

// ——————————————————————————————
// Produce on *all* outgoing edges of `act`, then update downstream flags
// ——————————————————————————————
void produce_actor(actor_t act, index_t idx) {
  actor_t dst;
  bool all_in;
  for (e : edges_t) {
    if (edges[e].from == act) {
      // place the token
      edge_token[e][idx] = true;
      // recompute readiness for the destination actor
      dst = edges[e].to;
      all_in = true;
      for (er : edges_t) {
        if (edges[er].to == dst && not edge_token[er][idx]) {
          all_in = false;
        }
      }
      actor_ready[dst][idx] = all_in;
    }
  }
}


// ——————————————————————————————
// Consume incoming token for `act`, then update its own flag
// ——————————————————————————————
void consume_actor(actor_t act, index_t idx) {
  // Local variables must be declared up front
  bool      all_in;
  index_t   next;

  // clear our own readiness at the current slot
  actor_ready[act][idx] = false;

  // clear tokens on all incoming edges at current slot
  for (e : edges_t) {
    if (edges[e].to == act) {
      edge_token[e][idx] = false;
    }
  }

  // compute the next buffer slot (circular)
  next = (idx + 1) % MAX_TOKENS;

  // check if *all* incoming edges have a token at 'next'
  all_in = true;
  for (er : edges_t) {
    if (edges[er].to == act && not edge_token[er][next]) {
      all_in = false;
    }
  }

  // u pdate readiness for the next slot
  actor_ready[act][next] = all_in;
}

template.declaration:
clock r;
int m = -1;
int n = 0;

nta.system:
