actor_t id13 = 13; // F
actor_t id14 = 14; // G_start
actor_t id15 = 15; // G
actor_t id16 = 16; // I_start
actor_t id17 = 17; // I

// WCET ranges per actor
const int LOW_1 = 245, HIGH_1 = 1081; // A
const int LOW_2 = 0, HIGH_2 = 0; // B_start
const int LOW_3 = 0, HIGH_3 = 0; // C_start
const int LOW_4 = 0, HIGH_4 = 0; // D_start
