const int LOW_6 = 21, HIGH_6 = 2589; // B
const int LOW_7 = 13, HIGH_7 = 660; // C
const int LOW_8 = 38, HIGH_8 = 323; // D
const int LOW_9 = 16, HIGH_9 = 45; // H
const int LOW_10 = 0, HIGH_10 = 0; // E_start
const int LOW_11 = 823, HIGH_11 = 19510; // E
const int LOW_12 = 0, HIGH_12 = 0; // F_start
const int LOW_13 = 394, HIGH_13 = 1159; // F
const int LOW_14 = 0, HIGH_14 = 0; // G_start
const int LOW_15 = 206, HIGH_15 = 1260; // G
const int LOW_16 = 0, HIGH_16 = 0; // I_start
const int LOW_17 = 227, HIGH_17 = 1791; // I

// Actor instantiations
actorA = ActorStart(id1, LOW_1, HIGH_1);
actorBs = Actor(id2, LOW_2, HIGH_2);
actorCs = Actor(id3, LOW_3, HIGH_3);
actorDs = Actor(id4, LOW_4, HIGH_4);
actorHs = Actor(id5, LOW_5, HIGH_5);
actorB = Actor(id6, LOW_6, HIGH_6);
actorC = Actor(id7, LOW_7, HIGH_7);
actorD = Actor(id8, LOW_8, HIGH_8);
actorH = Actor(id9, LOW_9, HIGH_9);
actorEs = Actor(id10, LOW_10, HIGH_10);
actorE = Actor(id11, LOW_11, HIGH_11);
actorFs = Actor(id12, LOW_12, HIGH_12);
actorF = Actor(id13, LOW_13, HIGH_13);
actorGs = Actor(id14, LOW_14, HIGH_14);
actorG = Actor(id15, LOW_15, HIGH_15);
actorIs = Actor(id16, LOW_16, HIGH_16);
actorI = ActorFinish(id17, LOW_17, HIGH_17);

system actorA, actorBs, actorCs, actorDs, actorHs, actorB, actorC, actorD, actorH, actorEs, actorE, actorFs, actorF, actorGs, actorG, actorIs, actorI, Dummy, Timer;
